<?php
if(!isset($manager,$user)){http_response_code(404);exit;}
$counts=[];foreach(['inquiry','confirmed','hold']as $status)$counts[$status]=(int)$manager->query('SELECT COUNT(*) AS n FROM bookings WHERE status=?',[$status])[0]['n'];
$counts['failed']=(int)$manager->query("SELECT COUNT(*) AS n FROM notification_outbox WHERE status='failed'")[0]['n'];
$today=date('Y-m-d');$arrivals=$manager->query("SELECT * FROM bookings WHERE status='confirmed' AND check_in>=? ORDER BY check_in LIMIT 5",[$today]);$departures=$manager->query("SELECT * FROM bookings WHERE status='confirmed' AND check_out>=? ORDER BY check_out LIMIT 5",[$today]);$recent=$manager->query('SELECT * FROM bookings ORDER BY id DESC LIMIT 6');
?>
<div class="metrics"><?php foreach(['inquiry'=>['Enquiries to review','bookings'],'confirmed'=>['Confirmed stays','bookings'],'hold'=>['Reservations','calendar'],'failed'=>['Failed emails','mail']]as $status=>$metric):?><a class="metric" href="<?=ae(au($metric[1],$status==='inquiry'?['status'=>'inquiry']:[]))?>"><span><?=ae($metric[0])?></span><strong><?=$counts[$status]?></strong></a><?php endforeach;?></div>
<div class="actions"><a class="button" href="<?=ae(au('bookings',['new'=>1]))?>">Create a booking</a><a class="button secondary" href="<?=ae(au('calendar'))?>">View calendar</a><a class="button secondary" href="<?=ae(au('content'))?>">Edit website</a></div>
<?php if((int)$app->setting('max_guests','0')<1):?><p class="alert hold">Set the real guest capacity and stay limits in <a href="<?=ae(au('settings'))?>">House settings</a> before creating bookings.</p><?php endif;?>
<div class="grid"><?php foreach(['Upcoming check-ins'=>$arrivals,'Upcoming check-outs'=>$departures]as $heading=>$rows):?><section class="card"><h2><?=ae($heading)?></h2><?php if(!$rows):?><p class="empty">No confirmed stays yet.</p><?php else:?><ul class="timeline"><?php foreach($rows as $booking):?><li><a href="<?=ae(au('bookings',['id'=>$booking['id']]))?>"><?=ae($booking['reference'])?></a> · <?=ae($booking['name'])?><br><small><?=ae($heading==='Upcoming check-ins'?$booking['check_in']:$booking['check_out'])?> · <?=(int)$booking['guests']?> guests</small></li><?php endforeach;?></ul><?php endif;?></section><?php endforeach;?></div>
<section class="card"><h2>Latest bookings</h2><?php if(!$recent):?><p class="empty">Bookings will appear here. You can register bookings received by phone or email even while public bookings are closed.</p><?php else:?><div class="scroll"><table><thead><tr><th>Reference</th><th>Guest</th><th>Stay</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($recent as $booking):?><tr><td><a href="<?=ae(au('bookings',['id'=>$booking['id']]))?>"><?=ae($booking['reference'])?></a></td><td><?=ae($booking['name'])?></td><td class="nowrap"><?=ae($booking['check_in'])?> → <?=ae($booking['check_out'])?></td><td><span class="badge <?=ae($booking['status'])?>"><?=ae($booking['status'])?></span></td><td class="nowrap"><?=money($booking['total_satang'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php require_once dirname(__DIR__).'/Readiness.php';$setup=\Cosmos\Readiness::setup($app);$readyCount=count(array_filter($setup,static fn($item)=>$item['ready']));$health=\Cosmos\Readiness::health($app); ?>
<div class="grid"><section class="card"><h2>Getting started <span class="setup-count"><?=$readyCount?> / <?=count($setup)?> ready</span></h2><?php foreach($setup as $item):?><div class="setup-row"><span><?php if(!$item['adminOnly']||$user['role']==='admin'):?><a href="<?=ae(au($item['view']))?>"><?=ae($item['label'])?></a><?php else:?><?=ae($item['label'])?><small>Managed by an administrator</small><?php endif;?></span><span class="badge <?=$item['ready']?'confirmed':'hold'?>"><?=$item['ready']?'Ready':(!empty($item['deferred'])?'Later':'Pending')?></span></div><?php endforeach;?><div class="actions"><a class="button secondary" href="<?=ae(au('guide'))?>">Read the staff guide</a></div></section>
<section class="card"><h2>Daily system checks</h2><?php foreach($health as $item):?><div class="setup-row"><span><?=ae($item['label'])?><small>Last successful run: <?=ae($item['last'])?> · Bangkok time</small></span><span class="badge <?=$item['ready']?'confirmed':'failed'?>"><?=$item['ready']?'Working':'Needs attention'?></span></div><?php endforeach;?><p class="help">Contact the site administrator if a system check needs attention. Public guest bookings remain closed until launch is reviewed.</p></section></div>
